const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const gobiDesert = ee.Geometry.Polygon([
    [[90, 45], [90, 40], [110, 40], [110, 45], [90, 45]]
  ]);

  const feb2019 = ['2019-02-01', '2019-03-01'];
  const feb2020 = ['2020-02-01', '2020-03-01'];

  // 2. Data Acquisition - MODIS AOD (Terra)
  const modisAOD = ee.ImageCollection('MODIS/061/MOD04_L2')
    .select('Optical_Depth_Land_And_Ocean')
    .filterBounds(gobiDesert);

  const aod2019 = modisAOD.filterDate(feb2019[0], feb2019[1]);
  const aod2020 = modisAOD.filterDate(feb2020[0], feb2020[1]);

  // Check collection sizes
  const count2019 = aod2019.size().getInfo();
  const count2020 = aod2020.size().getInfo();

  print(`2019 Images: ${count2019}, 2020 Images: ${count2020}`);

  if (count2019 === 0 || count2020 === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Create mean composites
  const mean2019 = aod2019.mean().multiply(0.001); // Scale factor
  const mean2020 = aod2020.mean().multiply(0.001);

  // Calculate mean AOD values
  const stats2019 = mean2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: gobiDesert,
    scale: 10000,
    maxPixels: 1e9
  });

  const stats2020 = mean2020.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: gobiDesert,
    scale: 10000,
    maxPixels: 1e9
  });

  const aodVal2019 = stats2019.get('Optical_Depth_Land_And_Ocean').getInfo();
  const aodVal2020 = stats2020.get('Optical_Depth_Land_And_Ocean').getInfo();

  // Check for valid pixels
  const countPixels2019 = mean2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: gobiDesert,
    scale: 10000,
    maxPixels: 1e9
  }).get('Optical_Depth_Land_And_Ocean').getInfo();

  const countPixels2020 = mean2020.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: gobiDesert,
    scale: 10000,
    maxPixels: 1e9
  }).get('Optical_Depth_Land_And_Ocean').getInfo();

  print(`AOD 2019: ${aodVal2019?.toFixed(4)}, Pixels: ${countPixels2019}`);
  print(`AOD 2020: ${aodVal2020?.toFixed(4)}, Pixels: ${countPixels2020}`);

  // 5. Validation & Final Answer
  if (aodVal2019 === null || aodVal2020 === null || 
      isNaN(aodVal2019) || isNaN(aodVal2020) ||
      countPixels2019 === 0 || countPixels2020 === 0) {
    print("<answer>C2</answer>");
  } else if (aodVal2019 < 0 || aodVal2020 < 0 || aodVal2019 > 5 || aodVal2020 > 5) {
    print("<answer>C3</answer>");
  } else if (aodVal2020 > aodVal2019) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
